M(cfg, r"""
public static Object[] gateList(String v, String[] why) {
  java.util.ArrayList sk = new java.util.ArrayList();
  java.util.ArrayList lv = new java.util.ArrayList();
  if (v != null && !v.trim().equalsIgnoreCase("none")) {
    String[] a = v.split("[,;]");
    for (int i = 0; i < a.length; i++) {
      String p = a[i].trim();
      if (p.length() == 0) continue;
      Object[] g = gateOf(p);
      if (g == null) { if (why != null && why[0] == null) why[0] = p; continue; }
      int at = sk.indexOf(g[0]);
      if (at >= 0) { if (((Integer) g[1]).intValue() > ((Integer) lv.get(at)).intValue()) lv.set(at, g[1]); continue; }
      sk.add(g[0]);
      lv.add(g[1]);
    }
  }
  String[] s = (String[]) sk.toArray(new String[sk.size()]);
  int[] l = new int[lv.size()];
  for (int i = 0; i < l.length; i++) l[i] = ((Integer) lv.get(i)).intValue();
  return new Object[] { s, l };
}""")
