# A3 bot flag: the gaps between a player's full breaks (under 10 s); after abuse.botSample of them, a spread (standard deviation) under
# abuse.botGapMs = flagged on /zones status (one admin log line) - NEVER a punishment
M(fair, r"""
public static void botAdd(@PKG@.ZPl p, long now) {
  long last = p.lastMs;
  p.lastMs = now;
  if (!@PKG@.ZCfg.BOT_FLAG || last <= 0L) return;
  long g = now - last;
  if (g < 0L || g >= 10000L) return;
  p.gaps[p.gn % 2000] = (int) g;
  p.gn = p.gn + 1;
  int n = Math.min(@PKG@.ZCfg.BOT_SAMPLE, 2000);
  if (p.gn < n || p.gn % 25 != 0) return;
  double sum = 0.0;
  for (int i = 0; i < n; i++) sum = sum + (double) p.gaps[(p.gn - 1 - i) % 2000];
  double mean = sum / (double) n;
  double var = 0.0;
  for (int i = 0; i < n; i++) { double d = (double) p.gaps[(p.gn - 1 - i) % 2000] - mean; var = var + d * d; }
  double sd = Math.sqrt(var / (double) n);
  if (sd >= (double) @PKG@.ZCfg.BOT_GAP_MS) return;
  boolean fresh = p.flag == null;
  p.flag = "rhythm spread " + Math.round(sd) + " ms over the last " + n + " breaks (one every " + Math.round(mean) + " ms)";
  p.flagAt = now;
  if (fresh) { FLAGGED.incrementAndGet(); @PKG@.ZCfg.info("fair play: " + p.name + " FLAGGED (no punishment) - " + p.flag + " (abuse.botGapMs " + @PKG@.ZCfg.BOT_GAP_MS + ")"); }
}""")
